  const b = data.filter(d => d.period==='基期' && d.channel===ch);
  const c = data.filter(d => d.period==='本期' && d.channel===ch);
  const bNet = b.reduce((s,d)=>s+d.net_sales_cents,0);
  const cNet = c.reduce((s,d)=>s+d.net_sales_cents,0);
  const bCon = b.reduce((s,d)=>s+d.contribution_cents,0);
  const cCon = c.reduce((s,d)=>s+d.contribution_cents,0);
