    channel: ch,
    基期净销售: bNet,
    本期净销售: cNet,
    净销售变化率: ((cNet-bNet)/bNet*100).toFixed(1)+'%',
    基期投放: bCon,
    本期投放: cCon,
    投放变化率: ((cCon-bCon)/bCon*100).toFixed(1)+'%',
    基期ROI: (bNet/bCon).toFixed(2),
    本期ROI: (cNet/cCon).toFixed(2)
  };
});
result = byChannel;

